package cklauncher

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"os"

	"github.com/GecEnterprises/corekiosk/go/ckframework"
)

// GameManifest records the packaged game binary metadata and integrity hash.
type GameManifest struct {
	Binary  string `json:"binary"`
	Version string `json:"version"`
	Engine  string `json:"engine,omitempty"`
	SHA256  string `json:"sha256,omitempty"`
}

// Manifest is generated by ckpack as dist/<app>/kiosk.manifest.json.
type Manifest struct {
	AppName            string       `json:"app_name"`
	AppVersion         string       `json:"app_version"`
	CKFrameworkVersion string       `json:"ckframework_version"`
	CKLauncherVersion  string       `json:"cklauncher_version"`
	ProtocolVersion    int          `json:"protocol_version"`
	MinClientVersion   string       `json:"min_client_version,omitempty"`
	Game               GameManifest `json:"game"`
	BuiltAt            string       `json:"built_at"`
}

func LoadManifest(path string) (*Manifest, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, ckframework.ErrNotFound.Wrap(err, "read kiosk manifest %s", path)
	}
	var m Manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, ckframework.ErrValidation.Wrap(err, "parse kiosk manifest")
	}
	return &m, nil
}

// HashFile computes the lowercase SHA-256 hex digest of a file (used for game binary integrity).
func HashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", ckframework.ErrNotFound.Wrap(err, "open file for hashing: %s", path)
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", ckframework.ErrInternal.Wrap(err, "hash file: %s", path)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}
